(function(root){'use strict';
const DB='nutri:local-personal:food:v2',MODE='local-personal';
const clone=x=>JSON.parse(JSON.stringify(x));
function failure(code){return Object.assign(Error(code),{code});}
function request(r){return new Promise((resolve,reject)=>{r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error||failure('LOCAL_READ_FAILED'));});}
function identity(s){if(!s||s.mode!==MODE||s.schemaVersion!==2||typeof s.accountId!=='string'||typeof s.epoch!=='string'||!Number.isInteger(s.revision)||!Array.isArray(s.records))throw failure('PERSONAL_STATE_INVALID');if(s.revision<0||!s.accountId||!s.epoch)throw failure('PERSONAL_STATE_INVALID');for(const row of s.records)validateRow(row);if(new Set(s.records.map(r=>r.id)).size!==s.records.length)throw failure('DUPLICATE_PERSONAL_RECORD');if(s.history){for(const rows of Object.values(s.history)){if(!Array.isArray(rows)||rows.length>5)throw failure('PERSONAL_HISTORY_INVALID');rows.forEach(validateRow);}}return{mode:s.mode,accountId:s.accountId,epoch:s.epoch,revision:s.revision};}
function same(a,b){return ['mode','accountId','epoch','revision'].every(k=>a?.[k]===b?.[k]);}
function stable(x){return x&&typeof x==='object'?(Array.isArray(x)?'['+x.map(stable).join(',')+']':'{'+Object.keys(x).sort().map(k=>JSON.stringify(k)+':'+stable(x[k])).join(',')+'}'):JSON.stringify(x);}
function validateRow(row){if(!row||row.synthetic!==false||row.scope!==MODE||typeof row.id!=='string'||!row.id||!row.name?.trim()||!Number.isInteger(row.revision)||row.revision<1||!/^\d{4}-\d{2}-\d{2}$/.test(row.date)||isNaN(Date.parse(row.date+'T12:00:00Z'))||new Date(row.date+'T12:00:00Z').toISOString().slice(0,10)!==row.date||!/^([01]\d|2[0-3]):[0-5]\d$/.test(row.time)||!['breakfast','lunch','dinner','snack'].includes(row.slot)||!row.nutrients||typeof row.nutrients!=='object')throw failure('PERSONAL_RECORD_INVALID');const registry=root.NutriFoodCaptureContract?.fields;if(!registry)throw failure('NUTRIENT_REGISTRY_REQUIRED');for(const [key,n] of Object.entries(row.nutrients)){if(registry[key]&&(n?.unit!==registry[key][1]||n?.basis!=='consumed'))throw failure('NUTRIENT_MIGRATION_REQUIRED');if(!n||!(n.value===null||typeof n.value==='number'&&Number.isFinite(n.value)&&n.value>=0)||typeof n.unit!=='string')throw failure('PERSONAL_NUTRIENT_INVALID');}const photos=row.photos===undefined?(row.photo?[row.photo]:[]):row.photos;if(!Array.isArray(photos)||photos.length>3||new Set(photos.map(p=>p.mediaId)).size!==photos.length||photos.some(p=>!p||typeof p.mediaId!=='string'||!p.mediaId||typeof p.sha256!=='string'||!/^image\/(jpeg|png|webp)$/.test(p.mime)||p.localOnly!==true))throw failure('PERSONAL_PHOTOS_INVALID');if(row.photos!==undefined&&stable(row.photo||null)!==stable(photos[0]||null))throw failure('PHOTO_PRIMARY_MISMATCH');return clone(row);}

function prepareCommit(row,media){const record=validateRow(row),list=media==null?[]:Array.isArray(media)?media:[media];if(list.length>3||new Set(list.map(m=>m?.id)).size!==list.length||list.some(m=>!m||!(m.blob instanceof Blob)||!m.id||!m.sha256||!/^image\/(jpeg|png|webp)$/.test(m.blob.type)||m.blob.size>8*1024*1024))throw failure('MEDIA_INVALID');const refs=record.photos===undefined?(record.photo?[record.photo]:[]):record.photos;record.photos=[...refs,...list.map(m=>({mediaId:m.id,sha256:m.sha256,mime:m.blob.type,localOnly:true}))];record.photo=record.photos[0]||null;validateRow(record);return{record,list};}
async function open({indexedDB:api=root.indexedDB,uuid=()=>root.crypto.randomUUID(),explicitConsent=false}={}){if(!explicitConsent)throw failure('PERSONAL_ENTRY_CONSENT_REQUIRED');if(!api)throw failure('INDEXEDDB_UNAVAILABLE');const opening=api.open(DB,1);opening.onupgradeneeded=()=>{const db=opening.result;for(const name of ['state','media','operations'])if(!db.objectStoreNames.contains(name))db.createObjectStore(name);};const db=await new Promise((resolve,reject)=>{let failed=false;opening.onblocked=()=>{failed=true;reject(failure('DATABASE_BLOCKED_CLOSE_OTHER_TABS'));};opening.onerror=()=>reject(opening.error);opening.onsuccess=()=>{if(failed){opening.result.close();return;}resolve(opening.result);};});db.onversionchange=()=>db.close();
await new Promise((resolve,reject)=>{const tx=db.transaction('state','readwrite'),store=tx.objectStore('state'),r=store.get('account');r.onsuccess=()=>{if(r.result!==undefined){try{identity(r.result);}catch(e){tx.abort();}}else{const key=store.getKey('account');key.onsuccess=()=>{if(key.result!==undefined){tx.abort();return;}store.put({schemaVersion:2,mode:MODE,accountId:uuid(),epoch:uuid(),revision:0,records:[],history:{},mediaBytes:0},'account');};}};tx.oncomplete=resolve;tx.onabort=()=>reject(tx.error||failure('PERSONAL_INITIALIZE_FAILED'));tx.onerror=()=>{};});
async function read(){const s=await request(db.transaction('state').objectStore('state').get('account'));identity(s);return clone(s);}
async function receipt(operationId){const r=await request(db.transaction('operations').objectStore('operations').get(operationId));if(r&&operationId.startsWith('migration:')){const validContext=c=>c?.mode===MODE&&typeof c.accountId==='string'&&!!c.accountId&&typeof c.epoch==='string'&&!!c.epoch&&Number.isInteger(c.revision)&&c.revision>=0;if(r.receiptVersion!==1||r.kind!=='migration'||r.operationId!==operationId||!/^migration:[a-f0-9]{64}$/.test(operationId)||r.sourceDigest!==operationId.slice(10)||r.signature!==stable({kind:'migration',source:r.sourceDigest})||!validContext(r.sourceIdentity)||!validContext(r.context)||r.context.revision!==r.sourceIdentity.revision||!Number.isInteger(r.mediaCount)||r.mediaCount<0||!Number.isInteger(r.mediaBytes)||r.mediaBytes<0||r.mediaBytes>64*1024*1024)throw failure('MIGRATION_RECEIPT_INVALID');const state=await read();if(state.accountId!==r.context.accountId||state.epoch!==r.context.epoch||state.revision<r.context.revision)throw failure('MIGRATION_DESTINATION_IDENTITY_MISMATCH');}return r?clone(r):null;}
async function commit({operationId,context,row,media=null}){if(typeof operationId!=='string'||!operationId)throw failure('OPERATION_ID_REQUIRED');const prepared=prepareCommit(row,media),record=prepared.record,list=prepared.list;const signature=stable({context,row:record,media:list.map(({id,sha256})=>({id,sha256}))});
let result;
await new Promise((resolve,reject)=>{const tx=db.transaction(['state','media','operations'],'readwrite'),states=tx.objectStore('state'),operations=tx.objectStore('operations');let reason=null;const fail=e=>{reason=e;tx.abort();};const prior=operations.get(operationId);prior.onsuccess=()=>{if(prior.result){if(prior.result.signature!==signature)return fail(failure('OPERATION_INPUT_CHANGED'));result=prior.result;return;}const proceed=()=>{const r=states.get('account');r.onsuccess=()=>{try{const state=r.result;if(!same(identity(state),context))throw failure('STALE_PERSONAL_CONTEXT');const index=state.records.findIndex(x=>x.id===record.id);if(index>=0){if(record.revision!==state.records[index].revision+1)throw failure('RECORD_REVISION_MISMATCH');state.history=state.history||{};state.history[record.id]=[...(state.history[record.id]||[]),clone(state.records[index])].slice(-5);state.records[index]=record;}else{if(record.revision!==1)throw failure('NEW_RECORD_REVISION_INVALID');if(state.records.length>=1000)throw failure('LOCAL_RECORD_LIMIT');state.records.push(record);}if(state.revision>=5000)throw failure('LOCAL_OPERATION_REVIEW_LIMIT');state.revision++;state.mediaBytes=(state.mediaBytes||0)+list.reduce((n,m)=>n+m.blob.size,0);if(state.mediaBytes>64*1024*1024)throw failure('LOCAL_MEDIA_BUDGET_EXCEEDED');for(const m of list)tx.objectStore('media').put({blob:m.blob,sha256:m.sha256},m.id);states.put(state,'account');result={operationId,signature,context:identity(state),recordId:record.id,recordRevision:record.revision};operations.put(result,operationId);}catch(e){fail(e);}};};let at=0;const checkNext=()=>{if(at===list.length){proceed();return;}const check=tx.objectStore('media').get(list[at++].id);check.onsuccess=()=>{if(check.result)return fail(failure('MEDIA_ID_ALREADY_EXISTS'));checkNext();};};checkNext();};tx.oncomplete=resolve;tx.onabort=()=>reject(reason||tx.error||failure('LOCAL_TRANSACTION_ABORTED'));tx.onerror=()=>{};});
try{const proof=await receipt(operationId);if(!proof||proof.signature!==signature)throw failure('RECEIPT_MISMATCH');return {status:'committed',receipt:proof,state:await read()};}catch(e){throw Object.assign(failure('COMMIT_RECEIPT_UNKNOWN'),{operationId,cause:e});}}
async function importSnapshot({snapshot,operationId}){snapshot=await root.NutriPersonalFoodTransfer.validate(snapshot);if(operationId!=='migration:'+snapshot.digest)throw failure('MIGRATION_OPERATION_MISMATCH');if(!snapshot||typeof operationId!=='string'||!operationId.startsWith('migration:'))throw failure('MIGRATION_INPUT_INVALID');const source=clone(snapshot.state);source.schemaVersion=2;identity(source);const media=snapshot.media;if(!Array.isArray(media)||media.reduce((n,m)=>n+m.blob.size,0)!==source.mediaBytes||source.mediaBytes>64*1024*1024)throw failure('MIGRATION_MEDIA_INVALID');const signature=stable({kind:'migration',source:snapshot.digest});const validProof=r=>!!r&&r.receiptVersion===1&&r.operationId===operationId&&r.signature===signature&&r.kind==='migration'&&r.sourceDigest===snapshot.digest&&stable(r.sourceIdentity)===stable(snapshot.sourceIdentity)&&r.mediaCount===media.length&&r.mediaBytes===source.mediaBytes&&r.context?.mode===MODE&&typeof r.context.accountId==='string'&&!!r.context.accountId&&typeof r.context.epoch==='string'&&!!r.context.epoch&&r.context.revision===source.revision;let result;await new Promise((resolve,reject)=>{const tx=db.transaction(['state','media','operations'],'readwrite');let reason;const fail=e=>{reason=e;tx.abort();};const ops=tx.objectStore('operations'),prior=ops.get(operationId);prior.onsuccess=()=>{if(prior.result){if(!validProof(prior.result))return fail(failure('MIGRATION_RECEIPT_INVALID'));result=prior.result;return;}const current=tx.objectStore('state').get('account'),mediaKeys=tx.objectStore('media').getAllKeys(),operationKeys=ops.getAllKeys();let remaining=3;const inspectEmpty=()=>{if(--remaining)return;try{const before=current.result;identity(before);if(before.revision!==0||before.records.length||before.mediaBytes||Object.keys(before.history||{}).length||mediaKeys.result.length||operationKeys.result.length)throw failure('MIGRATION_DESTINATION_NOT_EMPTY');const next={...source,accountId:before.accountId,epoch:uuid(),schemaVersion:2};for(const m of media)tx.objectStore('media').put({blob:m.blob,sha256:m.sha256},m.id);tx.objectStore('state').put(next,'account');result={receiptVersion:1,operationId,signature,kind:'migration',sourceIdentity:snapshot.sourceIdentity,sourceDigest:snapshot.digest,context:identity(next),mediaCount:media.length,mediaBytes:source.mediaBytes};ops.put(result,operationId);}catch(e){fail(e);}};current.onsuccess=inspectEmpty;mediaKeys.onsuccess=inspectEmpty;operationKeys.onsuccess=inspectEmpty;};tx.oncomplete=resolve;tx.onabort=()=>reject(reason||tx.error||failure('MIGRATION_ABORTED'));tx.onerror=()=>{};});try{const proof=await receipt(operationId);if(!validProof(proof))throw failure('MIGRATION_RECEIPT_MISMATCH');const state=await read();if(state.accountId!==proof.context.accountId||state.epoch!==proof.context.epoch||state.revision<proof.context.revision)throw failure('MIGRATION_DESTINATION_IDENTITY_MISMATCH');return{status:'committed',receipt:proof,state};}catch(e){throw Object.assign(failure('MIGRATION_RECEIPT_UNKNOWN'),{operationId});}}
return {read,commit,receipt,importSnapshot,signatureOf:({context,row,media})=>{const p=prepareCommit(row,media);return stable({context,row:p.record,media:p.list.map(({id,sha256})=>({id,sha256}))});},media:async id=>(await request(db.transaction('media').objectStore('media').get(id)))?.blob,close:()=>db.close(),identity};}
root.NutriPersonalFoodStore={open,identity,validateRow,same,stable,DB};if(typeof module!=='undefined')module.exports=root.NutriPersonalFoodStore;
})(typeof window!=='undefined'?window:globalThis);
